app ColumnBench {
    state hits: Int32 = 0
    body {
        Column(gap: 4) {
            Text("Reached end \(hits)")
            FastList(count: 5000, rowHeight: 8, hideVerticalScrollbar: true) { index in
                Spacer(height: 8)
            }.onEndReached { hits = hits + 1 }
        }
    }
}
